const W = +(p.get('w') || 1080), H = +(p.get('h') || 1350), S = +(p.get('s') || 1);
const BAND = +(p.get('band') || 420);
const r = document.documentElement.style;
r.setProperty('--W', W + 'px');
r.setProperty('--H', H + 'px');
r.setProperty('--s', S);
r.setProperty('--band', BAND + 'px');
if (p.get('steps') === 'row') document.body.classList.add('row');

// report fit for verification
window.fitReport = () => {
  const f = document.getElementById('flyer');
  const kids = [...f.children];
  const natural = kids.reduce((a, el) => a + el.getBoundingClientRect().height, 0);
  return {
    canvas: [W, H],
    naturalContent: Math.round(natural),
    slack: Math.round(H - natural),
    sections: kids.map(el => el.className + ':' + Math.round(el.getBoundingClientRect().height)),
    overflowX: f.scrollWidth - W,
    clipped: kids.some(el => {
      const b = el.getBoundingClientRect();
      return b.bottom > H + 0.6 || b.top < -0.6;
    })
  };
};

