async () => {
  const out = {};
  for (const f of ['portrait.png','wide.png','sky.png']) {
    const b = await (await fetch('/' + f + '?t=' + Date.now())).blob();
    const bm = await createImageBitmap(b);
    out[f] = bm.width + 'x' + bm.height;
  }
  return out;
}

